  &lt;<span class="th-token th-tag">Icon</span> <span class="th-token th-attr">sx</span>={<span class="th-token th-function">css</span>({ <span class="th-token th-property">width</span>: <span class="th-token th-string">&quot;1.25rem&quot;</span>, <span class="th-token th-property">height</span>: <span class="th-token th-string">&quot;1.25rem&quot;</span> })} /&gt;
